{{ config(
            materialized='table',
                post_hook={
                    "sql": "CREATE OR REPLACE TABLE `MAPLEMONK.Freakins_GRN_Factitems` AS SELECT PO_Code, CASE WHEN PO_Date IS NOT NULL AND PO_Date <> \'\' THEN CAST(PARSE_DATETIME(\'%Y-%m-%d %H:%M:%S\', PO_Date) AS DATE) ELSE NULL END AS PO_Date, PO_Type, coalesce(fsm.product_category,Category) Category, coalesce(fsm.style_code) Style_Code, Facility, GRN_Code, CASE WHEN GRN_Date IS NOT NULL AND GRN_Date <> \'\' THEN CAST(PARSE_DATETIME(\'%Y-%m-%d %H:%M:%S\', GRN_Date) AS DATE) ELSE NULL END AS GRN_Date, Batch_Code, Vendor_Code, Vendor_Name, trim(Item_SkuCode) Item_SkuCode, GRN_Created_By, GRN_Invoice_No, Item_Type_Name, Item_Type_Size, Vendor_SkuCode, Facility Warehouse_Name, Grn_item_Status, Item_Type_Brand, Item_Type_Color, CASE WHEN GRN_Invoice_Date IS NOT NULL AND GRN_Invoice_Date <> \'\' THEN SAFE_CAST(PARSE_DATE(\'%Y-%m-%d\', GRN_Invoice_Date) AS DATE) ELSE NULL END AS GRN_Invoice_Date, Rejection_Reason, CASE WHEN Total_Quantity_Received <> \'\' THEN CAST(Total_Quantity_Received AS INT64) end AS Quantity_Received, CASE WHEN Quantity_Rejected <> \'\' THEN CAST(Quantity_Rejected AS INT64) end AS Quantity_Rejected, CASE WHEN Percentage_Rejection <> \'\' then CAST(Percentage_Rejection AS FLOAT64) end AS Percentage_Rejection, CASE WHEN Values_of_Goods_Received_with_taxes <> \'\' then CAST(Values_of_Goods_Received_with_taxes AS FLOAT64) end AS GRN_Received_Value_with_taxes, CASE WHEN Values_of_Goods_Received_without_taxes <> \'\' then CAST(Values_of_Goods_Received_without_taxes AS FLOAT64) end AS GRN_Received_Value_without_taxes, CASE WHEN GRN_Date IS NOT NULL AND GRN_Date <> \'\' THEN SAFE_CAST(PARSE_DATETIME(\'%Y-%m-%d %H:%M:%S\', GRN_Date) AS DATETIME) ELSE NULL END AS GRN_Received_Timestamp, CASE WHEN (CASE WHEN GRN_Date IS NOT NULL AND GRN_Date <> \'\' THEN SAFE_CAST(PARSE_DATETIME(\'%Y-%m-%d %H:%M:%S\', GRN_Date) AS DATE) END) > DATE_SUB(CURRENT_DATE(), INTERVAL 30 DAY) THEN \'0-30\' WHEN (CASE WHEN GRN_Date IS NOT NULL AND GRN_Date <> \'\' THEN SAFE_CAST(PARSE_DATETIME(\'%Y-%m-%d %H:%M:%S\', GRN_Date) AS DATE) END) > DATE_SUB(CURRENT_DATE(), INTERVAL 60 DAY) THEN \'30-60\' WHEN (CASE WHEN GRN_Date IS NOT NULL AND GRN_Date <> \'\' THEN SAFE_CAST(PARSE_DATETIME(\'%Y-%m-%d %H:%M:%S\', GRN_Date) AS DATE) END) > DATE_SUB(CURRENT_DATE(), INTERVAL 90 DAY) THEN \'60-90\' WHEN (CASE WHEN GRN_Date IS NOT NULL AND GRN_Date <> \'\' THEN SAFE_CAST(PARSE_DATETIME(\'%Y-%m-%d %H:%M:%S\', GRN_Date) AS DATE) END) > DATE_SUB(CURRENT_DATE(), INTERVAL 120 DAY) THEN \'90-120\' WHEN (CASE WHEN GRN_Date IS NOT NULL AND GRN_Date <> \'\' THEN SAFE_CAST(PARSE_DATETIME(\'%Y-%m-%d %H:%M:%S\', GRN_Date) AS DATE) END) > DATE_SUB(CURRENT_DATE(), INTERVAL 180 DAY) THEN \'120-180\' WHEN (CASE WHEN GRN_Date IS NOT NULL AND GRN_Date <> \'\' THEN SAFE_CAST(PARSE_DATETIME(\'%Y-%m-%d %H:%M:%S\', GRN_Date) AS DATE) END) > DATE_SUB(CURRENT_DATE(), INTERVAL 270 DAY) THEN \'180-270\' WHEN (CASE WHEN GRN_Date IS NOT NULL AND GRN_Date <> \'\' THEN SAFE_CAST(PARSE_DATETIME(\'%Y-%m-%d %H:%M:%S\', GRN_Date) AS DATE) END) > DATE_SUB(CURRENT_DATE(), INTERVAL 360 DAY) THEN \'270-360\' ELSE \'360+\' END AS Bucket, CASE WHEN (CASE WHEN GRN_Date IS NOT NULL AND GRN_Date <> \'\' THEN SAFE_CAST(PARSE_DATETIME(\'%Y-%m-%d %H:%M:%S\', GRN_Date) AS DATE) ELSE NULL END) > DATE_SUB(CURRENT_DATE(), INTERVAL 30 DAY) THEN \'0-30\' ELSE \'30+\' END AS Extra_Bucket, Putaway_Code, CASE WHEN Putaway_Created IS NOT NULL AND Putaway_Created <> \'\' THEN CAST(PARSE_DATETIME(\'%Y-%m-%d %H:%M:%S\', Putaway_Created) AS DATE) ELSE NULL END AS Putaway_Date, FROM maplemonk.unicommerce_get_grn_report g LEFT JOIN ( SELECT * FROM MAPLEMONK.FREAKINS_FINALL_SKU_MASTER QUALIFY ROW_NUMBER() OVER (PARTITION BY LOWER(variant_sku) ORDER BY size) = 1 ) FSM ON LOWER(g.Item_SkuCode) = LOWER(fsm.variant_sku) WHERE UPPER(Facility) like any (\'%DLDRK%\',\'%BHIWANDI%\'); create or replace table maplemonk.freakins_inventory_ageing_consolidated as WITH inventory_ledger as ( select sku_code as sku, cast(parse_date(\'%d-%b-%y\',date) as date) as Date, sum(cast(Closing_Balance as int64)) as Inventory from maplemonk.freakins_inventory_ledger group by 1,2 ), first_grn_date as ( select item_skucode, min(grn_date) first_grn_date from `MAPLEMONK.Freakins_GRN_Factitems` group by 1 ), daily_grn as ( SELECT g.*, case when g.date_day = f.first_grn_date then 1 else 0 end as first_grn_flag from ( SELECT DISTINCT c.date_day, g.item_skucode, g.style_code, g.category FROM `MAPLEMONK.Freakins_GRN_Factitems` AS g CROSS JOIN ( SELECT date_day FROM UNNEST(GENERATE_DATE_ARRAY(DATE_TRUNC(DATE_SUB(CURRENT_DATE(),INTERVAL 2 YEAR), YEAR), CURRENT_DATE())) AS date_day) AS c ) g LEFT JOIN first_grn_date f on f.item_skucode = g.item_skucode WHERE g.date_day >= f.first_grn_date ), GRN AS( select date(dg.date_day) as date, dg.item_skucode, dg.style_code, dg.Category, sum(ifnull(Quantity_Received,0)) + sum(case when first_grn_flag = 1 then i.inventory else 0 end) as Received_Quantity, sum(ifnull(Quantity_Rejected,0)) as Rejected_Quantity from daily_grn dg left join `MAPLEMONK.Freakins_GRN_Factitems` g on dg.date_day = cast(g.grn_date as date) and dg.item_skucode = g.item_skucode and dg.category = g.category and dg.style_code = g.style_code left join inventory_ledger i on i.date = dg.date_day and dg.item_skucode = i.sku group by 1,2,3,4 order by 1 desc ), grn_date_wise AS ( select date as date, date_trunc(mg.date,month) as month, mg.item_skucode, mg.style_code, mg.Category, CASE WHEN DATE_DIFF(CURRENT_DATE(), date, day) <= 30 THEN \'0-30\' WHEN DATE_DIFF(CURRENT_DATE(), date, day) <= 60 THEN \'30-60\' WHEN DATE_DIFF(CURRENT_DATE(), date, day) <= 90 THEN \'60-90\' WHEN DATE_DIFF(CURRENT_DATE(), date, day) <= 120 THEN \'90-120\' WHEN DATE_DIFF(CURRENT_DATE(), date, day) <= 150 THEN \'120-150\' WHEN DATE_DIFF(CURRENT_DATE(), date, day) <= 180 THEN \'150-180\' WHEN DATE_DIFF(CURRENT_DATE(), date, day) <= 210 THEN \'180-210\' WHEN DATE_DIFF(CURRENT_DATE(), date, day) <= 240 THEN \'210-240\' WHEN DATE_DIFF(CURRENT_DATE(), date, day) <= 270 THEN \'240-270\' END as Inventory_Ageing_Bucket, sum(ifnull(mg.Received_Quantity,0)) - sum(ifnull(mg.Rejected_Quantity,0)) as Daily_Received_Quantity from grn mg group by 1,2,3,4,5,6 ), grn_total as ( select item_skucode, category, style_code, sum(ifnull(Received_Quantity,0)) - sum(ifnull(Rejected_Quantity,0)) as Total_Inwarded_Quantity from grn group by 1,2,3 ), grn_cummulative as ( select g.date, g.month, g.item_skucode, g.style_code, g.category, sum(ifnull(g1.Daily_Received_Quantity,0)) as Cummulative_Quantity from grn_date_wise g left join grn_date_wise g1 on g1.date < g.date and g1.item_skucode = g.item_skucode and g1.category = g.category and g1.style_code = g.style_code group by 1,2,3,4,5 ), grn_cummulative_incl as ( select g.date, g.month, g.style_code, g.item_skucode, g.category, sum(ifnull(g1.Daily_Received_Quantity,0)) as Incl_Cummulative_Quantity from grn_date_wise g left join grn_date_wise g1 on g1.date <= g.date and g1.item_skucode = g.item_skucode and g1.category = g.category and g1.style_code = g.style_code group by 1,2,3,4,5 ), sales_pre as ( select s.*, SUM(quantity) OVER (PARTITION BY sku,Product_category,style_code ORDER BY order_date ASC, reference_code ASC, saleorderitemcode ASC ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS cumulative_sold from `MAPLEMONK.Freakins_db_sales_consolidated` AS s ), sales_with_grn as ( select s.*, g.date as grn_date from sales_pre s inner join grn_cummulative_incl g on s.sku = g.item_skucode and s.Product_Category = g.category and s.style_code = g.style_code where (s.cumulative_sold - s.quantity) < g.incl_Cummulative_Quantity and s.cumulative_sold <= g.incl_Cummulative_Quantity qualify row_number() over (partition by s.reference_code,s.saleorderitemcode order by g.date asc) = 1 ), grn_sales_data as ( select sku, product_category, style_code, grn_date, max(date(order_date)) last_order_date_against_grn, sum(ifnull(quantity,0)) grn_sales, sum(case when date_diff(date(order_date),grn_date,day) <= 30 then quantity end) N30_grn_sales, sum(case when date_diff(date(order_date),grn_date,day) <= 60 then quantity end) N60_grn_sales, sum(case when date_diff(date(order_date),grn_date,day) <= 90 then quantity end) N90_grn_sales, sum(case when date_diff(date(order_date),grn_date,day) <= 180 then quantity end) N180_grn_sales, sum(case when date_diff(date(order_date),grn_date,day) <= 360 then quantity end) N360_grn_sales from sales_with_grn group by 1,2,3,4 ), daily_sales as ( Select s.* From ( SELECT DISTINCT c.date_day, s.sku, s.style_code, s.Product_Category_Main as product_category, FROM `MAPLEMONK.Freakins_db_sales_consolidated` AS s CROSS JOIN ( SELECT date_day FROM UNNEST(GENERATE_DATE_ARRAY(DATE_TRUNC(DATE_SUB(CURRENT_DATE(),INTERVAL 2 YEAR), YEAR), CURRENT_DATE())) AS date_day) AS c ) s LEFT JOIN first_grn_date f ON lower(f.item_skucode) = lower(s.sku) WHERE s.date_day >= f.first_grn_date ), sales AS ( select date(ds.date_day) as date, ds.sku as sku, ds.style_code, ds.Product_Category, sum(ifnull(Quantity,0)) as Sold_Quantity from daily_sales ds left join `MAPLEMONK.Freakins_db_sales_consolidated` s on ds.date_day = cast(s.order_date as date) and lower(ds.sku) = lower(s.sku) and lower(ds.product_category) = lower(s.Product_Category_Main) and lower(ds.style_code) = lower(s.style_code) group by 1,2,3,4 ), sales_final as ( select si.*, sum(ifnull(si.sold_quantity,0)) OVER (PARTITION BY sku,product_category,style_code ORDER BY DATE ROWS BETWEEN CURRENT ROW AND 6 FOLLOWING) AS N7_day_sales, sum(ifnull(si.sold_quantity,0)) OVER (PARTITION BY sku,product_category,style_code ORDER BY DATE ROWS BETWEEN CURRENT ROW AND 14 FOLLOWING) AS N14_day_sales, sum(ifnull(si.sold_quantity,0)) OVER (PARTITION BY sku,product_category,style_code ORDER BY DATE ROWS BETWEEN CURRENT ROW AND 29 FOLLOWING) AS N30_day_sales, sum(ifnull(si.sold_quantity,0)) OVER (PARTITION BY sku,product_category,style_code ORDER BY DATE ROWS BETWEEN CURRENT ROW AND 44 FOLLOWING) AS N45_day_sales, sum(ifnull(si.sold_quantity,0)) OVER (PARTITION BY sku,product_category,style_code ORDER BY DATE ROWS BETWEEN CURRENT ROW AND 59 FOLLOWING) AS N60_day_sales, sum(ifnull(si.sold_quantity,0)) OVER (PARTITION BY sku,product_category,style_code ORDER BY DATE ROWS BETWEEN CURRENT ROW AND 89 FOLLOWING) AS N90_day_sales, sum(ifnull(si.sold_quantity,0)) OVER (PARTITION BY sku,product_category,style_code ORDER BY DATE ROWS BETWEEN CURRENT ROW AND 179 FOLLOWING) AS N180_day_sales, sum(ifnull(si.sold_quantity,0)) OVER (PARTITION BY sku,product_category,style_code ORDER BY DATE ROWS BETWEEN CURRENT ROW AND 359 FOLLOWING) AS N360_day_sales from sales si ), sales_cummulative as ( select s.date, s.sku, s.style_code, s.Product_Category, sum(ifnull(s1.N7_day_sales,0)) as N7_cummulative_sales, sum(ifnull(s1.N14_day_sales,0)) as N14_cummulative_sales, sum(ifnull(s1.N30_day_sales,0)) as N30_cummulative_sales, sum(ifnull(s1.N45_day_sales,0)) as N45_cummulative_sales, sum(ifnull(s1.N60_day_sales,0)) as N60_cummulative_sales, sum(ifnull(s1.N90_day_sales,0)) as N90_cummulative_sales, sum(ifnull(s1.N180_day_sales,0)) as N180_cummulative_sales, sum(ifnull(s1.N360_day_sales,0)) as N360_cummulative_sales from (select * from sales_final where concat(date,lower(sku),lower(product_category),lower(style_code)) in (select concat(date,lower(item_skucode),lower(category),lower(style_code)) from grn_date_wise) ) s left join (select * from sales_final where concat(date,lower(sku),lower(product_category),lower(style_code)) in (select concat(date,lower(item_skucode),lower(category),lower(style_code)) from grn_date_wise)) s1 on s1.date <= s.date and s1.sku = s.sku and s1.Product_Category = s.Product_Category and s1.style_code = s.style_code group by 1,2,3,4 ), current_stock as ( SELECT Data_Fetch_Date, Sku, style_code, category, Available_Inventory FROM ( SELECT Data_Fetch_Date, UPPER(sku) SKU, upper(style_code) style_code, upper(category) category, Available_Inventory, ROW_NUMBER() OVER (PARTITION BY UPPER(Sku),upper(category),upper(style_code) ORDER BY Data_Fetch_Date DESC) AS rw FROM maplemonk.FREAKINS_SKUWISE_INVENTORY_FACT_ITEMS where Inventory_Type IN (\'GOOD_INVENTORY\') ) WHERE rw = 1 ), category_current_stock as ( SELECT Data_Fetch_Date, category, sum(ifnull(Available_Inventory,0)) Available_Inventory FROM maplemonk.FREAKINS_SKUWISE_INVENTORY_FACT_ITEMS where Inventory_Type IN (\'GOOD_INVENTORY\') and data_fetch_date = (select max(data_fetch_date) from maplemonk.FREAKINS_SKUWISE_INVENTORY_FACT_ITEMS) GROUP by 1,2 ), style_current_stock as ( SELECT Data_Fetch_Date, style_code, sum(ifnull(Available_Inventory,0)) Available_Inventory FROM maplemonk.FREAKINS_SKUWISE_INVENTORY_FACT_ITEMS where Inventory_Type IN (\'GOOD_INVENTORY\') and data_fetch_date = (select max(data_fetch_date) from maplemonk.FREAKINS_SKUWISE_INVENTORY_FACT_ITEMS) GROUP by 1,2 ) select g.*, sm.Product_ID, sm.Product_title, s.N7_day_sales, s.N14_day_sales, s.N30_day_sales, s.N60_day_sales, s.N90_day_sales, s.N180_day_sales, s.N360_day_sales, s.Sold_Quantity as Sold_Quantity_Daily, cs.available_inventory as Current_Stock, ccs.available_inventory as Category_Current_Stock, scs.available_inventory as Style_Current_Stock, gcl.Incl_Cummulative_Quantity, gc.Cummulative_Quantity, CASE WHEN (gt.Total_Inwarded_Quantity - cs.available_inventory) < (gc.Cummulative_Quantity + g.Daily_Received_Quantity) THEN CASE WHEN gc.Cummulative_Quantity > (gt.Total_Inwarded_Quantity - cs.available_inventory) THEN g.Daily_Received_Quantity ELSE g.Daily_Received_Quantity - ((gt.Total_Inwarded_Quantity - cs.available_inventory) - gc.Cummulative_Quantity) END ELSE 0 END as Aged_Inventory, gs.N30_grn_sales, gs.N60_grn_sales, gs.N90_grn_sales, gs.N180_grn_sales, gs.N360_grn_sales, (ifnull(g.Daily_Received_Quantity,0) - ifnull(gs.grn_sales,0)) as Current_Ageing_Inventory from grn_date_wise g left join sales_final s on s.date = g.date and s.sku = g.item_skucode and s.product_category = g.category and lower(s.style_code) = lower(g.style_code) left join `MAPLEMONK.FREAKINS_FINALL_SKU_MASTER` sm on lower(replace(sm.variant_sku,\' \',\'\')) = lower(g.item_skucode) left join current_stock cs on lower(cs.sku) = lower(g.item_skucode) and lower(cs.category) = lower(g.category) and lower(cs.style_code) = lower(g.style_code) left join category_current_stock ccs on lower(ccs.category) = lower(g.category) left join style_current_stock scs on lower(scs.style_code) = lower(g.style_code) left join grn_total gt on lower(gt.item_skucode) = lower(g.item_skucode) and lower(gt.category) = lower(g.category) and lower(gt.style_code) = lower(g.style_code) left join grn_cummulative gc on lower(gc.item_skucode) = lower(g.item_skucode) and gc.date = g.date and lower(gc.category) = lower(g.category) and lower(gc.style_code) = lower(g.style_code) left join grn_cummulative_incl gcl on lower(gcl.item_skucode) = lower(g.item_skucode) and gcl.date = g.date and lower(gcl.category) = lower(g.category) and lower(gcl.style_code) = lower(g.style_code) left join sales_cummulative sc on lower(sc.sku) = lower(g.item_skucode) and sc.date = g.date and lower(sc.product_category) = lower(g.category) and lower(sc.style_code) = lower(g.style_code) left join grn_sales_data gs on lower(gs.sku) = lower(g.item_skucode) and gs.grn_date = g.date and lower(gs.product_category) = lower(g.category) and lower(gs.style_code) = lower(g.style_code) ; create or replace table maplemonk.freakins_inventory_ageing_consolidated_putaway as WITH inventory_ledger as ( select sku_code as sku, cast(parse_date(\'%d-%b-%y\',date) as date) as Date, sum(cast(Closing_Balance as int64)) as Inventory from maplemonk.freakins_inventory_ledger group by 1,2 ), first_putaway_date as ( select item_skucode, min(putaway_date) first_putaway_date from `MAPLEMONK.Freakins_GRN_Factitems` group by 1 ), daily_grn as ( SELECT g.*, case when g.date_day = f.first_putaway_date then 1 else 0 end as first_putaway_flag from ( SELECT DISTINCT c.date_day, g.item_skucode, g.style_code, g.category FROM `MAPLEMONK.Freakins_GRN_Factitems` AS g CROSS JOIN ( SELECT date_day FROM UNNEST(GENERATE_DATE_ARRAY(DATE_TRUNC(DATE_SUB(CURRENT_DATE(),INTERVAL 2 YEAR), YEAR), CURRENT_DATE())) AS date_day) AS c ) g LEFT JOIN first_putaway_date f on f.item_skucode = g.item_skucode WHERE g.date_day >= f.first_putaway_date ), GRN AS( select date(dg.date_day) as date, dg.item_skucode, dg.style_code, dg.Category, sum(ifnull(Quantity_Received,0)) + sum(case when first_putaway_flag = 1 then i.inventory else 0 end) as Received_Quantity, sum(ifnull(Quantity_Rejected,0)) as Rejected_Quantity from daily_grn dg left join `MAPLEMONK.Freakins_GRN_Factitems` g on dg.date_day = cast(g.putaway_date as date) and dg.item_skucode = g.item_skucode and dg.category = g.category and dg.style_code = g.style_code left join inventory_ledger i on i.date = dg.date_day and dg.item_skucode = i.sku group by 1,2,3,4 order by 1 desc ), putaway_date_wise AS ( select date as date, date_trunc(mg.date,month) as month, mg.item_skucode, mg.style_code, mg.Category, CASE WHEN DATE_DIFF(CURRENT_DATE(), date, day) <= 30 THEN \'0-30\' WHEN DATE_DIFF(CURRENT_DATE(), date, day) <= 60 THEN \'30-60\' WHEN DATE_DIFF(CURRENT_DATE(), date, day) <= 90 THEN \'60-90\' WHEN DATE_DIFF(CURRENT_DATE(), date, day) <= 120 THEN \'90-120\' WHEN DATE_DIFF(CURRENT_DATE(), date, day) <= 150 THEN \'120-150\' WHEN DATE_DIFF(CURRENT_DATE(), date, day) <= 180 THEN \'150-180\' WHEN DATE_DIFF(CURRENT_DATE(), date, day) <= 210 THEN \'180-210\' WHEN DATE_DIFF(CURRENT_DATE(), date, day) <= 240 THEN \'210-240\' WHEN DATE_DIFF(CURRENT_DATE(), date, day) <= 270 THEN \'240-270\' END as Inventory_Ageing_Bucket, sum(ifnull(mg.Received_Quantity,0)) - sum(ifnull(mg.Rejected_Quantity,0)) as Daily_Received_Quantity, from grn mg group by 1,2,3,4,5,6 ), putaway_total as ( select item_skucode, category, style_code, sum(ifnull(Received_Quantity,0)) - sum(ifnull(Rejected_Quantity,0)) as Total_Inwarded_Quantity from grn group by 1,2,3 ), putaway_cummulative as ( select g.date, g.month, g.item_skucode, g.style_code, g.category, sum(ifnull(g1.Daily_Received_Quantity,0)) as Cummulative_Quantity from putaway_date_wise g left join putaway_date_wise g1 on g1.date < g.date and g1.item_skucode = g.item_skucode and g1.category = g.category and g1.style_code = g.style_code group by 1,2,3,4,5 ), putaway_cummulative_incl as ( select g.date, g.month, g.style_code, g.item_skucode, g.category, sum(ifnull(g1.Daily_Received_Quantity,0)) as Incl_Cummulative_Quantity from putaway_date_wise g left join putaway_date_wise g1 on g1.date <= g.date and g1.item_skucode = g.item_skucode and g1.category = g.category and g1.style_code = g.style_code group by 1,2,3,4,5 ), sales_pre as ( select s.*, SUM(quantity) OVER (PARTITION BY sku,Product_category,style_code ORDER BY order_date ASC, reference_code ASC, saleorderitemcode ASC ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS cumulative_sold from `MAPLEMONK.Freakins_db_sales_consolidated` AS s ), sales_with_putaway as ( select s.*, g.date as putaway_date from sales_pre s inner join putaway_cummulative_incl g on lower(coalesce(s.master_sku,s.sku)) = lower(g.item_skucode) and s.Product_Category = g.category and s.style_code = g.style_code where (s.cumulative_sold - s.quantity) < g.incl_Cummulative_Quantity and s.cumulative_sold <= g.incl_Cummulative_Quantity qualify row_number() over (partition by s.reference_code,s.saleorderitemcode order by g.date asc) = 1 ), putaway_sales_data as ( select sku, product_category, style_code, putaway_date, max(date(order_date)) last_order_date_against_putaway, sum(ifnull(quantity,0)) putaway_sales, sum(case when date_diff(date(order_date),putaway_date,day) <= 30 then quantity end) N30_putaway_sales, sum(case when date_diff(date(order_date),putaway_date,day) <= 60 then quantity end) N60_putaway_sales, sum(case when date_diff(date(order_date),putaway_date,day) <= 90 then quantity end) N90_putaway_sales, sum(case when date_diff(date(order_date),putaway_date,day) <= 180 then quantity end) N180_putaway_sales, sum(case when date_diff(date(order_date),putaway_date,day) <= 360 then quantity end) N360_putaway_sales from sales_with_putaway group by 1,2,3,4 ), daily_sales as ( Select s.* From ( SELECT DISTINCT c.date_day, s.sku, s.Product_Category_Main as product_category, s.style_code, FROM `MAPLEMONK.Freakins_db_sales_consolidated` AS s CROSS JOIN ( SELECT date_day FROM UNNEST(GENERATE_DATE_ARRAY(DATE_TRUNC(DATE_SUB(CURRENT_DATE(),INTERVAL 2 YEAR), YEAR), CURRENT_DATE())) AS date_day) AS c ) s LEFT JOIN first_putaway_date f ON lower(f.item_skucode) = lower(s.sku) WHERE s.date_day >= f.first_putaway_date ), sales AS ( select date(ds.date_day) as date, ds.sku as sku, ds.style_code, ds.Product_Category, sum(ifnull(Quantity,0)) as Sold_Quantity from daily_sales ds left join `MAPLEMONK.Freakins_db_sales_consolidated` s on ds.date_day = cast(s.order_date as date) and lower(ds.sku) = lower(coalesce(s.master_sku,s.sku)) and lower(ds.product_category) = lower(s.Product_Category_Main) and lower(ds.style_code) = lower(s.style_code) group by 1,2,3,4 ), sales_final as ( select si.*, sum(ifnull(si.sold_quantity,0)) OVER (PARTITION BY sku,product_category,style_code ORDER BY DATE ROWS BETWEEN CURRENT ROW AND 6 FOLLOWING) AS N7_day_sales, sum(ifnull(si.sold_quantity,0)) OVER (PARTITION BY sku,product_category,style_code ORDER BY DATE ROWS BETWEEN CURRENT ROW AND 14 FOLLOWING) AS N14_day_sales, sum(ifnull(si.sold_quantity,0)) OVER (PARTITION BY sku,product_category,style_code ORDER BY DATE ROWS BETWEEN CURRENT ROW AND 29 FOLLOWING) AS N30_day_sales, sum(ifnull(si.sold_quantity,0)) OVER (PARTITION BY sku,product_category,style_code ORDER BY DATE ROWS BETWEEN CURRENT ROW AND 44 FOLLOWING) AS N45_day_sales, sum(ifnull(si.sold_quantity,0)) OVER (PARTITION BY sku,product_category,style_code ORDER BY DATE ROWS BETWEEN CURRENT ROW AND 59 FOLLOWING) AS N60_day_sales, sum(ifnull(si.sold_quantity,0)) OVER (PARTITION BY sku,product_category,style_code ORDER BY DATE ROWS BETWEEN CURRENT ROW AND 89 FOLLOWING) AS N90_day_sales, sum(ifnull(si.sold_quantity,0)) OVER (PARTITION BY sku,product_category,style_code ORDER BY DATE ROWS BETWEEN CURRENT ROW AND 179 FOLLOWING) AS N180_day_sales, sum(ifnull(si.sold_quantity,0)) OVER (PARTITION BY sku,product_category,style_code ORDER BY DATE ROWS BETWEEN CURRENT ROW AND 359 FOLLOWING) AS N360_day_sales from sales si ), sales_cummulative as ( select s.date, s.sku, s.style_code, s.Product_Category, sum(ifnull(s1.N7_day_sales,0)) as N7_cummulative_sales, sum(ifnull(s1.N14_day_sales,0)) as N14_cummulative_sales, sum(ifnull(s1.N30_day_sales,0)) as N30_cummulative_sales, sum(ifnull(s1.N45_day_sales,0)) as N45_cummulative_sales, sum(ifnull(s1.N60_day_sales,0)) as N60_cummulative_sales, sum(ifnull(s1.N90_day_sales,0)) as N90_cummulative_sales, sum(ifnull(s1.N180_day_sales,0)) as N180_cummulative_sales, sum(ifnull(s1.N360_day_sales,0)) as N360_cummulative_sales from (select * from sales_final where concat(date,lower(sku),lower(product_category),lower(style_code)) in (select concat(date,lower(item_skucode),lower(category),lower(style_code)) from putaway_date_wise) ) s left join (select * from sales_final where concat(date,lower(sku),lower(product_category),lower(style_code)) in (select concat(date,lower(item_skucode),lower(category),lower(style_code)) from putaway_date_wise)) s1 on s1.date <= s.date and s1.sku = s.sku and s1.Product_Category = s.Product_Category and s1.style_code = s.style_code group by 1,2,3,4 ), current_stock as ( SELECT Data_Fetch_Date, Sku, style_code, category, Available_Inventory FROM ( SELECT Data_Fetch_Date, UPPER(sku) SKU, upper(style_code) style_code, upper(category) category, Available_Inventory, ROW_NUMBER() OVER (PARTITION BY UPPER(Sku),upper(category),upper(style_code) ORDER BY Data_Fetch_Date DESC) AS rw FROM maplemonk.FREAKINS_SKUWISE_INVENTORY_FACT_ITEMS where Inventory_Type IN (\'GOOD_INVENTORY\') ) WHERE rw = 1 ), category_current_stock as ( SELECT Data_Fetch_Date, category, sum(ifnull(Available_Inventory,0)) Available_Inventory FROM maplemonk.FREAKINS_SKUWISE_INVENTORY_FACT_ITEMS where Inventory_Type IN (\'GOOD_INVENTORY\') and data_fetch_date = (select max(data_fetch_date) from maplemonk.FREAKINS_SKUWISE_INVENTORY_FACT_ITEMS) GROUP by 1,2 ), style_current_stock as ( SELECT Data_Fetch_Date, style_code, sum(ifnull(Available_Inventory,0)) Available_Inventory FROM maplemonk.FREAKINS_SKUWISE_INVENTORY_FACT_ITEMS where Inventory_Type IN (\'GOOD_INVENTORY\') and data_fetch_date = (select max(data_fetch_date) from maplemonk.FREAKINS_SKUWISE_INVENTORY_FACT_ITEMS) GROUP by 1,2 ) select g.*, sm.Product_ID, sm.Product_title, s.N7_day_sales, s.N14_day_sales, s.N30_day_sales, s.N60_day_sales, s.N90_day_sales, s.N180_day_sales, s.N360_day_sales, s.Sold_Quantity as Sold_Quantity_Daily, cs.available_inventory as Current_Stock, ccs.available_inventory as Category_Current_Stock, scs.available_inventory as Style_Current_Stock, gcl.Incl_Cummulative_Quantity, gc.Cummulative_Quantity, CASE WHEN (gt.Total_Inwarded_Quantity - cs.available_inventory) < (gc.Cummulative_Quantity + g.Daily_Received_Quantity) THEN CASE WHEN gc.Cummulative_Quantity > (gt.Total_Inwarded_Quantity - cs.available_inventory) THEN g.Daily_Received_Quantity ELSE g.Daily_Received_Quantity - ((gt.Total_Inwarded_Quantity - cs.available_inventory) - gc.Cummulative_Quantity) END ELSE 0 END as Aged_Inventory, gs.N30_putaway_sales, gs.N60_putaway_sales, gs.N90_putaway_sales, gs.N180_putaway_sales, gs.N360_putaway_sales, (ifnull(g.Daily_Received_Quantity,0) - ifnull(gs.putaway_sales,0)) as Current_Ageing_Inventory from putaway_date_wise g left join sales_final s on s.date = g.date and s.sku = g.item_skucode and s.product_category = g.category and lower(s.style_code) = lower(g.style_code) left join `MAPLEMONK.FREAKINS_FINALL_SKU_MASTER` sm on lower(replace(sm.variant_sku,\' \',\'\')) = lower(g.item_skucode) left join current_stock cs on lower(cs.sku) = lower(g.item_skucode) and lower(cs.category) = lower(g.category) and lower(cs.style_code) = lower(g.style_code) left join category_current_stock ccs on lower(ccs.category) = lower(g.category) left join style_current_stock scs on lower(scs.style_code) = lower(g.style_code) left join putaway_total gt on lower(gt.item_skucode) = lower(g.item_skucode) and lower(gt.category) = lower(g.category) and lower(gt.style_code) = lower(g.style_code) left join putaway_cummulative gc on lower(gc.item_skucode) = lower(g.item_skucode) and gc.date = g.date and lower(gc.category) = lower(g.category) and lower(gc.style_code) = lower(g.style_code) left join putaway_cummulative_incl gcl on lower(gcl.item_skucode) = lower(g.item_skucode) and gcl.date = g.date and lower(gcl.category) = lower(g.category) and lower(gcl.style_code) = lower(g.style_code) left join sales_cummulative sc on lower(sc.sku) = lower(g.item_skucode) and sc.date = g.date and lower(sc.product_category) = lower(g.category) and lower(sc.style_code) = lower(g.style_code) left join putaway_sales_data gs on lower(gs.sku) = lower(g.item_skucode) and gs.putaway_date = g.date and lower(gs.product_category) = lower(g.category) and lower(gs.style_code) = lower(g.style_code) ;",
                    "transaction": true
                }
            ) }}
            with sample_data as (

